<?php
namespace App\Http\Controllers;
use App\Http\Requests\StoreShiftRequest; use App\Modules\Operations\Models\{Assignment,Shift}; use Illuminate\Database\Eloquent\Builder; use Illuminate\Http\RedirectResponse; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB; use Illuminate\View\View;
class ShiftController extends Controller { public function index(Request $r): View { $q=Shift::query()->withCount(['assignments','checklists'])->when($r->filled('search'),fn(Builder $q)=>$q->where('name','like','%'.$r->string('search').'%'))->when($r->filled('status'),fn(Builder $q)=>$q->where('status',$r->string('status'))); return view('tenant.operations.shifts',['shifts'=>$q->orderBy('name')->paginate(10)->withQueryString(),'summary'=>['total'=>Shift::count(),'active'=>Shift::where('status','active')->count(),'inactive'=>Shift::where('status','inactive')->count(),'assigned'=>Assignment::count()]]); } public function create(): View { return view('tenant.operations.shift-form'); } public function store(StoreShiftRequest $r): RedirectResponse { $shift=Shift::create($r->validated()); return redirect()->route('operations.shifts.show',$shift)->with('success','Turno creado correctamente.'); } public function show(Shift $shift): View { return view('tenant.operations.shift-show',['shift'=>$shift,'inUse'=>$this->inUse($shift)]); } public function edit(Shift $shift): View { return view('tenant.operations.shift-form',compact('shift')); } public function update(StoreShiftRequest $r,Shift $shift): RedirectResponse { $shift->update($r->validated()); return redirect()->route('operations.shifts.show',$shift)->with('success','Turno actualizado correctamente.'); } public function toggle(Shift $shift): RedirectResponse { $shift->update(['status'=>$shift->status==='active'?'inactive':'active']); return back()->with('success','Estado del turno actualizado.'); } public function destroy(Shift $shift): RedirectResponse { if($this->inUse($shift)) return back()->withErrors(['shift'=>'Este turno tiene asignaciones, checklists o historial. Solo puede desactivarse.']); $shift->delete(); return redirect()->route('operations.shifts')->with('success','Turno eliminado.'); } private function inUse(Shift $shift): bool { return $shift->assignments()->exists() || $shift->checklists()->exists(); } }
